-- pretoria-east-property-valuation-la-montagne (owner)
UPDATE businesses SET description = 'Pretoria East Property Valuation provides property valuation and market-assessment services in Pretoria East, and also offers property sales and marketing. The practice is based at 218 Lavata Street in La Montagne, Pretoria, 0184. It serves property owners, buyers, sellers, investors and developers. The practice is led by a practitioner registered with the Property Practitioners Regulatory Authority (PPRA) as a Professional Practitioner in Real Estate. That practitioner has been involved in property sales and valuations since 2011, holds an MSc in Property Studies from the University of Cape Town, and is a Candidate Property Valuer registered with the SACPVP. Because the practice combines valuation with market assessment, clients can get a valuation and a view of local market conditions from the same provider.', description_enriched_at = datetime('now') WHERE slug = 'pretoria-east-property-valuation-la-montagne' AND description = 'Pretoria East Property Valuation is a PPRA-registered property valuation service in La Montagne, Pretoria East, operating since 2011 through a SACPVP Candidate Valuer holding an MSc in Property Studies.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
