UPDATE businesses SET description = 'RocoMamas Irene Village is a casual burger restaurant at Shop 93, Irene Village Mall, on Van Ryneveld Avenue in Irene Farm Villages, Centurion, 0133. It is part of the RocoMamas brand, and the brand''s official directory lists this branch. The menu centres on Smashburgers, hot chicken wings and ribs, in American diner style. Guests can dine in or take away, and independent sources also list delivery. According to the official directory, the branch opens from 08:30 to 21:00 from Sunday to Thursday, and from 08:30 to 22:00 on Friday and Saturday. Those opening hours are published by the brand itself, so visitors can plan a visit using the official schedule.', description_enriched_at = datetime('now') WHERE slug = 'rocomamas-irene-village-irene-farm-villages' AND description = 'RocoMamas Irene Village is a burger restaurant set in the open piazza of Irene Village Mall, Centurion, offering Smashburgers, Mofo Hot Chicken Wings, Rockin Ribs and a create-your-own-burger option.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
